/*
 * dir_$old_hash_name - hash an old-format directory entry name
 *
 * Original address: 0x00E54B58
 * Size: 70 bytes (0x00E54B58 .. 0x00E54B9D)
 * Generated by: Claude Opus 5.5
 *
 * Module-local routine of the OLD_DIR segment (no map symbol).  Callers:
 * dir_$old_find_entry (0x00E54C38), dir_$old_unlink_entry (0x00E5532A),
 * dir_$old_add_entry (0x00E5573E), DIR_$OLD_CNAMEU (0x00E576A6); each
 * keeps only D0w.
 *
 * Frame: (0x8,A6) name (A0), (0xC,A6) name_len word (D0), (0xE,A6)
 * num_buckets word (D1).
 *
 * Blocks:
 *   0x00E54B6C-0x00E54B88  h = 0; for i = 1..name_len (dbf):
 *                          h = h + h + name[i-1]  (16-bit)
 *   0x00E54B8C-0x00E54B92  D0 = h (zero-extended); divu.w num_buckets;
 *                          swap: the function result is h mod num_buckets
 *
 * Quirk: after the `swap' the high word of D0 holds the quotient; the
 * Pascal result is the low word only and no caller looks at the rest.  A
 * zero num_buckets takes the divide-by-zero trap, as in the image.
 */

#include "dir/dir_internal.h"

uint16_t dir_$old_hash_name(uint8_t *name, uint16_t name_len,
                            uint16_t num_buckets)
{
    uint16_t h = 0;                             /* D2 */
    uint16_t i;                                 /* D3 */

    /* 0x00E54B6C-0x00E54B88 */
    if (name_len != 0) {
        for (i = 1; i <= name_len; i++) {       /* dbf D0w */
            h = (uint16_t)(h + h);
            h = (uint16_t)(h + name[i - 1]);
        }
    }

    /* 0x00E54B8C-0x00E54B92 */
    return (uint16_t)((uint32_t)h % num_buckets);
}
